// ===== ⚡ GM：直接修改任一玩家的骰子（基礎攻擊／基礎血量／每面點數與詞條）=====
let gmDiceEditTargetNick = "", gmDiceEditPlayer = null;
let gmSparResult = null;
async function gmSetPlayerDiceStats(targetNick, dieId, atk, hp) {
  if (!ku()) { ac(dc("僅GM可使用", "GM only")); return null; }
  let updated;
  try {
    updated = await Wl(targetNick, p => {
      const die = p.dice && p.dice[dieId];
      if (!die) throw new Error("no die");
      die.baseAttack = Math.max(0, Math.round(atk));
      die.baseHp = Math.max(0, Math.round(hp));
    });
  } catch (e) {
    ac(dc("設定失敗，找不到這顆骰子或玩家，請重新載入後再試", "Failed — die or player not found, reload and try again"));
    return null;
  }
  if (updated) ac(dc(`⚡ 已更新 ${targetNick} 的骰子基礎攻擊／血量`, `⚡ Updated ${targetNick}'s die base ATK/HP`));
  return updated;
}
async function gmSetPlayerDiceFace(targetNick, dieId, faceIdx, num, effectId) {
  if (!ku()) { ac(dc("僅GM可使用", "GM only")); return null; }
  if (!(faceIdx >= 0 && faceIdx < 6)) { ac(dc("面編號錯誤", "Invalid face index")); return null; }
  if (!(num >= 1 && num <= 7)) { ac(dc("點數需為1-7", "Number must be 1-7")); return null; }
  let updated;
  try {
    updated = await Wl(targetNick, p => {
      const die = p.dice && p.dice[dieId];
      if (!die) throw new Error("no die");
      const eff = effectId ? ho.find(h => h.id === effectId) : null;
      die.faces[faceIdx] = { num: num, effect: eff ? { ...eff } : null };
    });
  } catch (e) {
    ac(dc("GM設定失敗，找不到這顆骰子或玩家，請重新載入後再試", "GM set failed — die or player not found, reload and try again"));
    return null;
  }
  if (updated) ac(dc(`⚡ 已設定 ${targetNick} 的骰子第 ${faceIdx + 1} 面`, `⚡ Set ${targetNick}'s die face #${faceIdx + 1}`));
  return updated;
}
